// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 withdrawAmount) internal {
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        try c.withdraw(withdrawAmount) {} catch { return; }
        try c.withdrawAll() {} catch { return; }
        uint256 afterCount;
        try c.depositsCount() returns (uint256 __r) { afterCount = __r; } catch { return; }
        assertTrue(afterCount == beforeCount);
    }

    function testFuzz_run(uint256 withdrawAmount) public {
        _run(withdrawAmount);
    }

    receive() external payable {}
}
